#include <stdio.h>
#include <stdlib.h>

int miller_rabin(long long n, int k) {
    if (n < 2) return 0;
    if (n == 2 || n == 3) return 1;
    if (n % 2 == 0) return 0;

    long long s = 0, d = n - 1;
    while (d % 2 == 0) {
        s++;
        d /= 2;
    }

    for (int i = 0; i < k; i++) {
        long long a = (rand() % (n - 2)) + 2;
        long long x = 1;
        for (int j = 0; j < s; j++) {
            x = (x * a) % n;
            if (x == 1 || x == n - 1) break;
        }
        if (x != n - 1) return 0;
    }
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 1;
    }
    long long n = strtoll(argv[1], NULL, 10);
    if (n < 0 || n > 4294967295) {
        printf("OUT_OF_RANGE\n");
        return 1;
    }
    if (miller_rabin(n, 5)) {
        printf("PRIME\n");
    } else {
        printf("NOT_PRIME\n");
    }
    return 0;
}
